import os
import subprocess
from pathlib import Path

def parse_env_file(filepath=".env"):
    secrets = {}
    if not os.path.exists(filepath):
        return secrets
    with open(filepath, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if "=" in line:
                k, v = line.split("=", 1)
                k = k.strip()
                v = v.strip().strip("'").strip('"')
                if k in ("AI_API_KEY", "ADMIN_PASSWORD", "SECRET_KEY"):
                    secrets[k] = v
    return secrets

def main():
    print("=" * 60)
    print("SECRETS SCAN & AUDIT")
    print("=" * 60)

    env_secrets = parse_env_file(".env")
    print("\n[1] Environment Secrets Loaded:")
    for key, val in env_secrets.items():
        if val:
            print(f"  {key}: length {len(val)} characters (value hidden)")
        else:
            print(f"  {key}: [EMPTY / NOT CONFIGURED]")

    patterns_to_check = {}
    patterns_to_check["Groq key prefix ('gsk_')"] = "gsk_"
    for k, v in env_secrets.items():
        if v and len(v) >= 4:
            patterns_to_check[f"Value of {k} ({len(v)} chars)"] = v

    # 1. Scan specified documentation files
    target_files = [
        Path("AI_SESSIONS.json"),
        Path("AI_USAGE.md"),
        Path("README.md"),
    ]
    ai_logs_dir = Path("ai-logs")
    if ai_logs_dir.exists():
        for p in ai_logs_dir.glob("*.md"):
            target_files.append(p)

    print("\n[2] Scanning Local Documentation Files:")
    doc_leaks = 0
    for target in target_files:
        if not target.exists():
            print(f"  {target}: NOT FOUND")
            continue
        try:
            content = target.read_text(encoding="utf-8", errors="ignore")
            found_any = False
            for label, pattern in patterns_to_check.items():
                if pattern in content:
                    print(f"  [ALERT] {target} contains pattern: {label}")
                    found_any = True
                    doc_leaks += 1
            if not found_any:
                print(f"  {target}: CLEAN (zero matches for all patterns)")
        except Exception as e:
            print(f"  {target}: ERROR reading file ({e})")

    # 2. Scan Git History
    print("\n[3] Scanning Git Commit History (git log --all -S):")
    git_leaks = 0
    for label, pattern in patterns_to_check.items():
        cmd = ["git", "log", "--all", "-S", pattern, "--oneline"]
        try:
            res = subprocess.run(cmd, capture_output=True, text=True, check=True)
            output = res.stdout.strip()
            if output:
                lines = output.splitlines()
                print(f"  [ALERT] Pattern '{label}' found in {len(lines)} commit(s)")
                git_leaks += 1
            else:
                print(f"  Pattern '{label}': NOT FOUND in git history")
        except subprocess.CalledProcessError as e:
            print(f"  Error running git log for {label}: {e}")

    print("\n[4] Scan Summary:")
    print(f"  Documentation leaks detected: {doc_leaks}")
    print(f"  Git history leaks detected:   {git_leaks}")
    if doc_leaks == 0 and git_leaks == 0:
        print("  RESULT: REPOSITORY AND DOCUMENTATION ARE 100% CLEAN OF SECRETS.")
    else:
        print("  RESULT: SECRETS FOUND! Review alerts above.")

if __name__ == "__main__":
    main()

