import os
import re
import json

def parse_env_secrets(env_path=".env"):
    secrets = {}
    if not os.path.exists(env_path):
        return secrets
    with open(env_path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if "=" in line:
                k, v = line.split("=", 1)
                k = k.strip()
                v = v.strip().strip("'").strip('"')
                if k in ("AI_API_KEY", "ADMIN_PASSWORD", "SECRET_KEY"):
                    secrets[k] = v
    return secrets

def main():
    ai_logs_dir = "ai-logs"
    s2_file = os.path.join(ai_logs_dir, "S2-antigravity.jsonl")

    # 1. Clean ai-logs directory: keep only S2-antigravity.jsonl
    if os.path.exists(ai_logs_dir):
        for fname in os.listdir(ai_logs_dir):
            if fname != "S2-antigravity.jsonl":
                fpath = os.path.join(ai_logs_dir, fname)
                try:
                    os.remove(fpath)
                    print(f"Removed non-S2 file: {fname}")
                except Exception as e:
                    print(f"Error removing {fname}: {e}")

    if not os.path.exists(s2_file):
        raise FileNotFoundError(f"{s2_file} does not exist!")

    # 2. Read .env secrets inside script (never print them)
    env_secrets = parse_env_secrets(".env")

    with open(s2_file, "r", encoding="utf-8") as f:
        content = f.read()

    # Redact regex: gsk_[A-Za-z0-9_\-]{20,}
    gsk_pattern = re.compile(r"gsk_[A-Za-z0-9_\-]{20,}")
    gsk_matches = len(gsk_pattern.findall(content))
    content = gsk_pattern.sub("[REDACTED]", content)
    print(f"Pattern 'gsk_[A-Za-z0-9_\\-]{{20,}}' replacements: {gsk_matches}")

    # Redact .env secrets (>= 8 chars) both as-is and json-escaped
    for secret_name, secret_val in env_secrets.items():
        if len(secret_val) >= 8:
            # as-is replacement
            count_raw = content.count(secret_val)
            if count_raw > 0:
                content = content.replace(secret_val, "[REDACTED]")

            # json-escaped replacement
            json_escaped = json.dumps(secret_val)[1:-1]
            count_json = 0
            if json_escaped != secret_val:
                count_json = content.count(json_escaped)
                if count_json > 0:
                    content = content.replace(json_escaped, "[REDACTED]")

            print(f"Secret '{secret_name}' (len {len(secret_val)}) replacements: raw={count_raw}, json_escaped={count_json}")
        else:
            print(f"Secret '{secret_name}' skipped (length < 8)")

    with open(s2_file, "w", encoding="utf-8") as f:
        f.write(content)

    print("\n--- VERIFICATION ---")
    # Verify every line parses with json.loads
    lines = content.splitlines()
    parse_errors = 0
    for idx, line in enumerate(lines, 1):
        line = line.strip()
        if not line:
            continue
        try:
            json.loads(line)
        except Exception as e:
            parse_errors += 1
            print(f"JSON parse error on line {idx}: {e}")

    if parse_errors == 0:
        print(f"Verification: all {len(lines)} lines successfully parsed with json.loads")
    else:
        raise ValueError(f"Verification failed: {parse_errors} lines failed json.loads")

    # Verify no match for gsk_[A-Za-z0-9]{10,}
    leak_gsk = re.search(r"gsk_[A-Za-z0-9]{10,}", content)
    if leak_gsk:
        print("Residual gsk_ pattern: found (FAIL)")
        raise ValueError("Residual gsk_ pattern found!")
    else:
        print("Residual gsk_ pattern: not found (PASS)")

    # Verify none of the .env values remain
    env_residual = False
    for secret_name, secret_val in env_secrets.items():
        if len(secret_val) >= 8:
            if secret_val in content:
                print(f"Residual '{secret_name}': found (FAIL)")
                env_residual = True
            else:
                print(f"Residual '{secret_name}': not found (PASS)")
            json_escaped = json.dumps(secret_val)[1:-1]
            if json_escaped in content:
                print(f"Residual '{secret_name}' (json-escaped): found (FAIL)")
                env_residual = True

    if env_residual:
        raise ValueError("Residual .env secrets found in redacted file!")

    print("\nTask 3 redaction and verification completed successfully!")

if __name__ == "__main__":
    main()

import os
import subprocess

def parse_env_secrets(env_path=".env"):
    secrets = {}
    if not os.path.exists(env_path):
        return secrets
    with open(env_path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if "=" in line:
                k, v = line.split("=", 1)
                k = k.strip()
                v = v.strip().strip("'").strip('"')
                if k in ("AI_API_KEY", "ADMIN_PASSWORD", "SECRET_KEY"):
                    secrets[k] = v
    return secrets

def main():
    print("=== GIT HISTORY SCAN ===")
    env_secrets = parse_env_secrets(".env")

    leaks = False

    # 1. Check each .env value with git log --all --oneline -S
    for name, val in env_secrets.items():
        if len(val) >= 8:
            cmd = ["git", "log", "--all", "--oneline", f"-S{val}"]
            res = subprocess.run(cmd, capture_output=True, text=True)
            output = res.stdout.strip()
            if output:
                lines = output.splitlines()
                hashes = [l.split()[0] for l in lines]
                print(f"Secret '{name}' (len {len(val)}): FOUND in commit(s): {hashes}")
                leaks = True
            else:
                print(f"Secret '{name}' (len {len(val)}): NOT FOUND in git history (PASS)")
        else:
            print(f"Secret '{name}': skipped (len < 8)")

    # 2. Check gsk_ pattern across all commits
    # Let's run git log --all -Sgsk_
    cmd_gsk = ["git", "log", "--all", "--oneline", "-Sgsk_"]
    res_gsk = subprocess.run(cmd_gsk, capture_output=True, text=True)
    out_gsk = res_gsk.stdout.strip()
    if out_gsk:
        lines = out_gsk.splitlines()
        hashes = [l.split()[0] for l in lines]
        print(f"Pattern 'gsk_': FOUND in commit(s): {hashes}")
        leaks = True
    else:
        print("Pattern 'gsk_': NOT FOUND in git log -S (PASS)")

    # Also test git grep -l "gsk_" across all revs
    try:
        revs = subprocess.check_output(["git", "rev-list", "--all"], text=True).splitlines()
        # Test in batches if needed
        grep_found = []
        for r in revs:
            grep_res = subprocess.run(["git", "grep", "-l", "gsk_", r], capture_output=True, text=True)
            if grep_res.stdout.strip():
                grep_found.append(f"{r[:7]}: {grep_res.stdout.strip()}")
        if grep_found:
            print(f"git grep 'gsk_' found in: {grep_found}")
            leaks = True
        else:
            print("git grep 'gsk_' across all revisions: NOT FOUND (PASS)")
    except Exception as e:
        print(f"Error checking rev-list: {e}")

    print("\n=== SCAN RESULT ===")
    if leaks:
        print("RESULT: LEAKS DETECTED! DO NOT PUSH.")
    else:
        print("RESULT: CLEAN! Zero secrets found in entire git history.")

if __name__ == "__main__":
    main()

