python -c "
import os

base_html = '''<!DOCTYPE html>
<html lang=\"en\">
<head>
  <meta charset=\"UTF-8\">
  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">
  <title>{% block title %}Kadak Chai Co. &mdash; #MyChaiBreak{% endblock %}</title>
  {% block head %}{% endblock %}
  <link rel=\"stylesheet\" href=\"/static/style.css\">
</head>
<body>
  <header class=\"site-header\">
    <div class=\"container brand-wrapper\">
      <h1 class=\"brand-title\"><a href=\"/\">Kadak Chai Co.</a></h1>
      <span class=\"campaign-tag\">#MyChaiBreak</span>
    </div>
  </header>

  <main class=\"container {% block main_class %}{% endblock %}\">
    {% block content %}{% endblock %}
  </main>

  <footer class=\"site-footer\">
    <div class=\"container\">
      <p>&copy; Kadak Chai Co. &bull; Celebrating the everyday rituals of tea, warmth, and conversation.</p>
      <p class=\"footer-disclaimer\">Kadak Chai Co. is a fictional brand created for a hiring assignment.</p>
    </div>
  </footer>

  {% block scripts %}{% endblock %}
</body>
</html>
'''

index_html = '''{% extends \"base.html\" %}

{% block title %}Kadak Chai Co. &mdash; Share Your #MyChaiBreak Story{% endblock %}

{% block content %}
<section class=\"hero-section\">
  <h2 class=\"hero-title\">Every cup of chai holds a story.</h2>
  <p class=\"hero-subtitle\">
    From roadside cutting stalls to quiet home brews on rainy evenings, share your favorite chai ritual with the community.
  </p>
  <div class=\"hero-art\" aria-hidden=\"true\">
    <svg viewBox=\"0 0 200 210\" width=\"160\" height=\"168\" xmlns=\"http://www.w3.org/2000/svg\">
      <!-- steam: three open curves, animated with CSS -->
      <path class=\"steam s1\" d=\"M86 78 C80 66 92 58 86 44\" />
      <path class=\"steam s2\" d=\"M100 76 C94 62 106 52 100 36\" />
      <path class=\"steam s3\" d=\"M114 78 C108 66 120 58 114 46\" />

      <!-- saucer: a flat ellipse under the cup -->
      <ellipse class=\"art-saucer\" cx=\"100\" cy=\"182\" rx=\"56\" ry=\"9\" />

      <!-- kulhad body: wide rim, narrow base, rounded bottom corners -->
      <path class=\"art-cup\" d=\"M58 92 L142 92 L128 172 Q127 178 121 178 L79 178 Q73 178 72 172 Z\" />
      <!-- decorative band: one curved line across the cup -->
      <path class=\"art-line\" d=\"M64 124 Q100 134 136 124\" />
      <!-- tea surface: rim ellipse, then a smaller darker ellipse inside it -->
      <ellipse class=\"art-rim\" cx=\"100\" cy=\"92\" rx=\"42\" ry=\"7\" />
      <ellipse class=\"art-tea\" cx=\"100\" cy=\"93\" rx=\"37\" ry=\"4.5\" />

      <!-- tea leaf (left): closed leaf shape plus a vein line -->
      <path class=\"art-leaf\" d=\"M16 196 Q24 166 52 170 Q48 196 16 196 Z\" />
      <path class=\"art-line\" d=\"M19 194 L46 173\" />

      <!-- cardamom pod (right): tilted ellipse plus a seam line -->
      <g transform=\"rotate(-20 162 190)\">
        <ellipse class=\"art-leaf\" cx=\"162\" cy=\"190\" rx=\"11\" ry=\"6\" />
        <path class=\"art-line\" d=\"M152 190 L172 190\" />
      </g>
    </svg>
  </div>
  <div class=\"rules-banner\">
    <strong>Campaign Guidelines:</strong> Stories must be about an authentic chai/tea break (10 to {{ max_story_length }} characters). Keep it wholesome, friendly, and respectful. Every entry is screened by AI, and our team can remove any entry.
  </div>
</section>

<ol class=\"steps\">
  <li>
    <svg viewBox=\"0 0 24 24\" width=\"28\" height=\"28\" fill=\"none\" stroke=\"currentColor\"
         stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">
      <path d=\"M4 5h16v11H10l-6 4z\" /><path d=\"M8 9h8M8 12h5\" />
    </svg>
    <span><strong>1.</strong> Share your memory</span>
  </li>
  <li>
    <svg viewBox=\"0 0 24 24\" width=\"28\" height=\"28\" fill=\"none\" stroke=\"currentColor\"
         stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">
      <path d=\"M12 3l1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8z\" /><path d=\"M19 16v4M17 18h4\" />
    </svg>
    <span><strong>2.</strong> AI brews your caption</span>
  </li>
  <li>
    <svg viewBox=\"0 0 24 24\" width=\"28\" height=\"28\" fill=\"none\" stroke=\"currentColor\"
         stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">
      <rect x=\"4\" y=\"4\" width=\"7\" height=\"7\" /><rect x=\"13\" y=\"4\" width=\"7\" height=\"7\" />
      <rect x=\"4\" y=\"13\" width=\"7\" height=\"7\" /><rect x=\"13\" y=\"13\" width=\"7\" height=\"7\" />
    </svg>
    <span><strong>3.</strong> Featured on the wall</span>
  </li>
</ol>

<section class=\"card\" id=\"submit-section\">
  <h3 class=\"card-title\">Brew &amp; Share Your Chai Story</h3>
  <form action=\"/submit\" method=\"POST\" novalidate>
    <div class=\"form-row\">
      <div class=\"form-group\">
        <label for=\"name\">Your Name</label>
        <input
          type=\"text\"
          id=\"name\"
          name=\"name\"
          value=\"{{ form_data.get('name', '') }}\"
          maxlength=\"100\"
          placeholder=\"e.g. Priya Sharma\"
          autocomplete=\"name\"
          class=\"{% if errors.get('name') %}is-invalid{% endif %}\"
          {% if errors.get('name') %}aria-describedby=\"name-error\"{% endif %}
          required
        >
        {% if errors.get('name') %}
          <span id=\"name-error\" class=\"error-msg\" role=\"alert\">{{ errors.name }}</span>
        {% endif %}
      </div>

      <div class=\"form-group\">
        <label for=\"city\">City / Town</label>
        <input
          type=\"text\"
          id=\"city\"
          name=\"city\"
          value=\"{{ form_data.get('city', '') }}\"
          maxlength=\"100\"
          placeholder=\"e.g. Jaipur\"
          autocomplete=\"address-level2\"
          class=\"{% if errors.get('city') %}is-invalid{% endif %}\"
          {% if errors.get('city') %}aria-describedby=\"city-error\"{% endif %}
          required
        >
        {% if errors.get('city') %}
          <span id=\"city-error\" class=\"error-msg\" role=\"alert\">{{ errors.city }}</span>
        {% endif %}
      </div>
    </div>

    <div class=\"form-group\">
      <label for=\"contact\">Contact Information (Email or Mobile)</label>
      <input
        type=\"text\"
        id=\"contact\"
        name=\"contact\"
        value=\"{{ form_data.get('contact', '') }}\"
        maxlength=\"255\"
        placeholder=\"e.g. priya@example.com or +91 98765 43210\"
        autocapitalize=\"none\"
        spellcheck=\"false\"
        class=\"{% if errors.get('contact') %}is-invalid{% endif %}\"
        {% if errors.get('contact') %}aria-describedby=\"contact-error\"{% endif %}
        required
      >
      <div class=\"field-hint\">
        We&rsquo;ll only reach out if your story is featured in the campaign. Never published.
      </div>
      {% if errors.get('contact') %}
        <span id=\"contact-error\" class=\"error-msg\" role=\"alert\">{{ errors.contact }}</span>
      {% endif %}
    </div>

    <div class=\"form-group\">
      <label for=\"story\">Your Chai Story</label>
      <textarea
        id=\"story\"
        name=\"story\"
        rows=\"6\"
        maxlength=\"{{ max_story_length }}\"
        placeholder=\"Tell us about the setting, the aroma, the conversations, or the quiet moment that made this chai break special...\"
        class=\"{% if errors.get('story') %}is-invalid{% endif %}\"
        {% if errors.get('story') %}aria-describedby=\"story-error\"{% endif %}
        required
      >{{ form_data.get('story', '') }}</textarea>
      <div class=\"char-counter\"><span id=\"char-count\">0</span> / {{ max_story_length }}</div>
      {% if errors.get('story') %}
        <span id=\"story-error\" class=\"error-msg\" role=\"alert\">{{ errors.story }}</span>
      {% endif %}
    </div>

    <div class=\"form-group checkbox-group\">
      <label class=\"checkbox-label\" for=\"consent\">
        <input
          type=\"checkbox\"
          id=\"consent\"
          name=\"consent\"
          value=\"true\"
          {% if form_data.get('consent') %}checked{% endif %}
          {% if errors.get('consent') %}aria-describedby=\"consent-error\"{% endif %}
        >
        <span>I confirm this is my own authentic story and agree to have it featured on the Kadak Chai Co. wall if approved.</span>
      </label>
      {% if errors.get('consent') %}
        <span id=\"consent-error\" class=\"error-msg\" role=\"alert\">{{ errors.consent }}</span>
      {% endif %}
    </div>

    <button type=\"submit\" class=\"btn btn-primary\" id=\"submit-btn\">Submit Chai Story</button>
  </form>
</section>

<section class=\"wall-section\">
  <div class=\"wall-header\">
    <h3 class=\"wall-title\">Approved #MyChaiBreak Stories</h3>
    <p class=\"wall-subtitle\">Recent stories celebrating warm cups and cherished moments across the country.</p>
  </div>

  {% if entries %}
    <div class=\"stories-grid\">
      {% for entry in entries %}
        <article class=\"story-card\">
          <div>
            {% if entry.ai_caption %}
              <h4 class=\"story-caption\">&ldquo;{{ entry.ai_caption }}&rdquo;</h4>
            {% endif %}
          </div>
          <div class=\"story-meta\">
            <span class=\"story-author\">&mdash; {{ entry.name.split()[0] }}</span>
            {% if entry.created_at %}
              <span class=\"story-date\">{{ entry.created_at.strftime('%B %d, %Y') }}</span>
            {% endif %}
            {% if entry.ai_category %}
              <span class=\"badge badge-category\">{{ entry.ai_category }}</span>
            {% endif %}
          </div>
        </article>
      {% endfor %}
    </div>
  {% else %}
    <div class=\"empty-wall-notice\">
      <p>Be the first to share your chai story.</p>
    </div>
  {% endif %}
</section>
{% endblock %}

{% block scripts %}
<script>
  (function () {
    var storyInput = document.getElementById(\"story\");
    var charCount = document.getElementById(\"char-count\");
    var counterBox = charCount ? charCount.parentElement : null;

    if (storyInput && charCount) {
      function updateCount() {
        var len = storyInput.value.length;
        charCount.textContent = len;
        if (counterBox) {
          if (len >= 300) {
            counterBox.style.color = \"#8c2424\";
            counterBox.style.fontWeight = \"700\";
          } else if (len >= 270) {
            counterBox.style.color = \"#d9822b\";
            counterBox.style.fontWeight = \"600\";
          } else {
            counterBox.style.color = \"\";
            counterBox.style.fontWeight = \"\";
          }
        }
      }
      storyInput.addEventListener(\"input\", updateCount);
      updateCount();
    }

    var submitForm = document.querySelector(\"form[action='/submit']\");
    var submitBtn = document.getElementById(\"submit-btn\");
    var originalBtnText = submitBtn ? submitBtn.textContent : \"Submit Chai Story\";

    if (submitForm && submitBtn) {
      submitForm.addEventListener(\"submit\", function () {
        setTimeout(function () {
          submitBtn.disabled = true;
          submitBtn.textContent = \"Brewing your caption...\";
        }, 0);
      });

      window.addEventListener(\"pageshow\", function () {
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.textContent = originalBtnText;
        }
      });
    }
  })();
</script>
{% endblock %}
'''

result_html = '''{% extends \"base.html\" %}

{% block title %}
  {% if entry.status == 'approved' %}
    Approved: #MyChaiBreak Story by {{ entry.name.split()[0] }}
  {% elif entry.status == 'rejected' %}
    Story Submission Update &mdash; Kadak Chai Co.
  {% else %}
    Story In Review &mdash; Kadak Chai Co.
  {% endif %}
{% endblock %}

{% block head %}
  {% if entry.status == 'approved' %}
    <meta property=\"og:title\" content=\"Kadak Chai Co. &mdash; #MyChaiBreak\">
    <meta property=\"og:description\" content=\"{{ entry.ai_caption }}\">
    <meta property=\"og:url\" content=\"{{ request.url }}\">
    <meta property=\"og:type\" content=\"website\">
    <meta name=\"twitter:card\" content=\"summary\">
  {% endif %}
{% endblock %}

{% block content %}
<div class=\"result-card\">
  <div class=\"result-header\">
    <h2 class=\"result-status-title\">Submission Outcome</h2>
    <div>
      {% if entry.status == 'approved' %}
        <span class=\"badge badge-approved\">Approved</span>
        {% if entry.ai_category %}
          <span class=\"badge badge-category\">{{ entry.ai_category }}</span>
        {% endif %}
      {% elif entry.status == 'rejected' %}
        <span class=\"badge badge-rejected\">Not Selected</span>
      {% else %}
        <span class=\"badge badge-pending\">Under Review</span>
      {% endif %}
    </div>
  </div>

  {% if entry.status == 'approved' %}
    <div class=\"result-approved-banner\">
      <strong>Congratulations, {{ entry.name.split()[0] }}!</strong> Your chai story has been accepted and is now featured on the public #MyChaiBreak wall.
    </div>

    <div class=\"poster-card\">
      {% if entry.ai_caption %}
        <blockquote class=\"poster-caption\">&ldquo;{{ entry.ai_caption }}&rdquo;</blockquote>
      {% endif %}
      <div class=\"poster-meta\">
        <span class=\"poster-author\">&mdash; {{ entry.name.split()[0] }}</span>
        {% if entry.created_at %}
          <span class=\"poster-date\">{{ entry.created_at.strftime('%B %d, %Y') }}</span>
        {% endif %}
      </div>
    </div>

  {% elif entry.status == 'rejected' %}
    <div class=\"result-rejected-banner\">
      <strong>Submission Update</strong>
      <p style=\"margin: 0.5rem 0 0;\">This story did not meet our campaign guidelines for the public wall.</p>
    </div>

    <p style=\"color: var(--chai-light);\">
      Our community wall focuses specifically on authentic personal chai-break moments. We warmly invite you to submit another story about your tea-time memories!
    </p>

  {% else %}
    <div class=\"result-pending-banner\">
      <strong>Submission In Review</strong>
      <p style=\"margin: 0.5rem 0 0;\">
        Thank you for submitting! Our team reviews pending submissions regularly. Please check back at this link soon.
      </p>
    </div>
  {% endif %}

  <div class=\"share-notice\">
    <strong>Bookmark or Share This Submission:</strong>
    <p style=\"margin: 0 0 0.5rem; color: var(--chai-light); font-size: 0.85rem;\">
      You can return to this page anytime to view your story status.
    </p>
    <div style=\"display: flex; gap: 0.5rem; flex-wrap: wrap; margin-bottom: 0.5rem;\">
      <input type=\"text\" readonly value=\"{{ request.url }}\" id=\"share-url-input\" class=\"share-link-input\" style=\"flex: 1 1 200px;\" onclick=\"this.select();\">
      <button type=\"button\" class=\"btn btn-secondary\" style=\"padding: 0.5rem 1rem; font-size: 0.9rem;\" onclick=\"copyShareLink()\">Copy link</button>
    </div>
    <span id=\"copy-status\" style=\"font-size: 0.85rem; color: var(--terracotta); font-weight: 600;\" aria-live=\"polite\"></span>
  </div>

  <div class=\"result-actions\">
    <a href=\"/\" class=\"btn btn-secondary\">&larr; Back to Stories Wall</a>
    {% if entry.status == 'approved' %}
      <a href=\"https://wa.me/?text=My%20%23MyChaiBreak%20story%3A%20{{ request.url }}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn btn-secondary\">Share on WhatsApp</a>
      <a href=\"/\" class=\"btn btn-primary\">Share another story</a>
    {% elif entry.status == 'rejected' or entry.status == 'pending_review' %}
      <a href=\"/#submit-section\" class=\"btn btn-primary\">Submit Another Story</a>
    {% endif %}
  </div>
</div>
{% endblock %}

{% block scripts %}
<script>
  function copyShareLink() {
    var input = document.getElementById(\"share-url-input\");
    var status = document.getElementById(\"copy-status\");
    var url = input ? input.value : window.location.href;
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(url).then(function() {
        if (status) status.textContent = \"Copied!\";
      }).catch(function() {
        fallbackCopy();
      });
    } else {
      fallbackCopy();
    }
    function fallbackCopy() {
      if (input) {
        input.select();
        input.setSelectionRange(0, 99999);
        try {
          document.execCommand(\"copy\");
          if (status) status.textContent = \"Copied!\";
        } catch (err) {
          if (status) status.textContent = \"Link selected\";
        }
      }
    }
  }
</script>
{% endblock %}
'''

admin_html = '''{% extends \"base.html\" %}
{% block title %}Admin &mdash; Kadak Chai Co.{% endblock %}
{% block main_class %}admin-container{% endblock %}
{% block content %}
<section class=\"card\">
  <div class=\"admin-bar\">
    <h3 class=\"card-title\">Entries</h3>
    <form action=\"/admin/logout\" method=\"POST\">
      <button type=\"submit\" class=\"btn btn-secondary\">Log out</button>
    </form>
  </div>

  <nav class=\"filter-bar\" aria-label=\"Filter by status\">
    {% for key, label in filters %}
      <a href=\"/admin?status={{ key }}\" class=\"filter-link{% if key == current %} is-active{% endif %}\">
        {{ label }} ({{ counts[key] }})
      </a>
    {% endfor %}
  </nav>

  {% if entries %}
    {% if counts[current] > limit %}
      <p><small>Showing the newest {{ limit }} of {{ counts[current] }}.</small></p>
    {% endif %}
    <div class=\"admin-cards-grid\">
      {% for e in entries %}
        <article class=\"admin-entry-card\" id=\"entry-{{ e.id }}\">
          <div class=\"admin-card-header\">
            <div class=\"admin-entry-title\">
              <span class=\"admin-entry-id\">#{{ e.id }}</span>
              <time class=\"admin-entry-time\">{{ e.created_at.strftime('%d %b %Y %H:%M') }} UTC</time>
            </div>
            <div class=\"admin-entry-status\">
              <span class=\"badge {% if e.status == 'approved' %}badge-approved{% elif e.status == 'rejected' %}badge-rejected{% else %}badge-pending{% endif %}\">{{ e.status }}</span>
              {% if e.admin_override %}
                <span class=\"overridden-tag\">overridden</span>
              {% endif %}
            </div>
          </div>

          <div class=\"admin-card-body\">
            <div class=\"admin-field-group\">
              <div class=\"admin-person\">
                <strong>{{ e.name }}</strong>
                <span class=\"admin-city\">({{ e.city }})</span>
              </div>
              <div class=\"admin-contact\">
                <code>{{ e.contact }}</code>
                <span class=\"admin-contact-type\">({{ e.contact_type }})</span>
              </div>
            </div>

            <div class=\"admin-story\">
              <strong>Story:</strong>
              <div class=\"admin-story-text\">{{ e.story }}</div>
            </div>

            <div class=\"admin-ai-result\">
              <strong>AI Result:</strong>
              {% if e.ai_decision %}
                <div class=\"admin-ai-details\">
                  <span class=\"admin-ai-badge\">{{ e.ai_decision }}</span> /
                  <span class=\"admin-ai-category\">{{ e.ai_category }}</span>
                  {% if e.ai_caption %}
                    <blockquote class=\"admin-ai-caption\">&ldquo;{{ e.ai_caption }}&rdquo;</blockquote>
                  {% endif %}
                  {% if e.ai_reason %}
                    <p class=\"admin-ai-reason\"><small>Reason: {{ e.ai_reason }}</small></p>
                  {% endif %}
                </div>
              {% else %}
                <div class=\"admin-ai-failed\">
                  <small>AI failed: {{ e.ai_error or 'unknown' }}</small>
                </div>
              {% endif %}
            </div>
          </div>

          <div class=\"admin-card-actions\">
            <form action=\"/admin/entries/{{ e.id }}/override\" method=\"POST\" class=\"admin-override-form\">
              <input type=\"hidden\" name=\"csrf_token\" value=\"{{ csrf }}\">
              <input type=\"hidden\" name=\"back\" value=\"{{ current }}\">
              {% if not e.ai_caption or e.ai_decision == 'rejected' %}
                <div class=\"override-caption-group\">
                  <input type=\"text\" name=\"caption\" maxlength=\"300\" placeholder=\"Caption (needed to approve)\" class=\"override-caption-input\">
                </div>
              {% endif %}
              <div class=\"override-buttons-group\">
                {% if e.status != 'approved' %}
                  <button type=\"submit\" name=\"decision\" value=\"approved\" class=\"btn btn-primary btn-sm\">Approve</button>
                {% endif %}
                {% if e.status != 'rejected' %}
                  <button type=\"submit\" name=\"decision\" value=\"rejected\" class=\"btn btn-secondary btn-sm\">Reject</button>
                {% endif %}
              </div>
            </form>
          </div>
        </article>
      {% endfor %}
    </div>
  {% else %}
    <p>No entries here.</p>
  {% endif %}
</section>
{% endblock %}
'''

for path, content in [
    ('app/templates/base.html', base_html),
    ('app/templates/index.html', index_html),
    ('app/templates/result.html', result_html),
    ('app/templates/admin_dashboard.html', admin_html),
]:
    with open(path, 'w', encoding='utf-8', newline='\n') as f:
        f.write(content)
    print('Wrote', path)
