args.Content:
{% extends "base.html" %}

{% block title %}Kadak Chai Co. &mdash; Share Your #MyChaiBreak Story{% endblock %}

{% block content %}
<section class="hero-section">
  <h2 class="hero-title">Every cup of chai holds a story.</h2>
  <p class="hero-subtitle">
    From roadside cutting stalls to quiet home brews on rainy evenings, share your favorite chai ritual with the community.
  </p>
  <div class="hero-art" aria-hidden="true">
    <svg viewBox="0 0 200 210" width="160" height="168" xmlns="http://www.w3.org/2000/svg">
      <!-- steam: three open curves, animated with CSS -->
      <path class="steam s1" d="M86 78 C80 66 92 58 86 44" />
      <path class="steam s2" d="M100 76 C94 62 106 52 100 36" />
      <path class="steam s3" d="M114 78 C108 66 120 58 114 46" />

      <!-- saucer: a flat ellipse under the cup -->
      <ellipse class="art-saucer" cx="100" cy="182" rx="56" ry="9" />

      <!-- kulhad body: wide rim, narrow base, rounded bottom corners -->
      <path class="art-cup" d="M58 92 L142 92 L128 172 Q127 178 121 178 L79 178 Q73 178 72 172 Z" />
      <!-- decorative band: one curved line across the cup -->
      <path class="art-line" d="M64 124 Q100 134 136 124" />
      <!-- tea surface: rim ellipse, then a smaller darker ellipse inside it -->
      <ellipse class="art-rim" cx="100" cy="92" rx="42" ry="7" />
      <ellipse class="art-tea" cx="100" cy="93" rx="37" ry="4.5" />

      <!-- tea leaf (left): closed leaf shape plus a vein line -->
      <path class="art-leaf" d="M16 196 Q24 166 52 170 Q48 196 16 196 Z" />
      <path class="art-line" d="M19 194 L46 173" />

      <!-- cardamom pod (right): tilted ellipse plus a seam line -->
      <g transform="rotate(-20 162 190)">
        <ellipse class="art-leaf" cx="162" cy="190" rx="11" ry="6" />
        <path class="art-line" d="M152 190 L172 190" />
      </g>
    </svg>
  </div>
  <div class="rules-banner">
    <strong>Campaign Guidelines:</strong> Stories must be about an authentic chai/tea break (10 to {{ max_story_length }} characters). Keep it wholesome, friendly, and respectful. Every entry is screened by AI, and our team can remove any entry.
  </div>
</section>

<ol class="steps">
  <li>
    <svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor"
         stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <path d="M4 5h16v11H10l-6 4z" /><path d="M8 9h8M8 12h5" />
    </svg>
    <span><strong>1.</strong> Share your memory</span>
  </li>
  <li>
    <svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor"
         stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <path d="M12 3l1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8z" /><path d="M19 16v4M17 18h4" />
    </svg>
    <span><strong>2.</strong> AI brews your caption</span>
  </li>
  <li>
    <svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor"
         stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <rect x="4" y="4" width="7" height="7" /><rect x="13" y="4" width="7" height="7" />
      <rect x="4" y="13" width="7" height="7" /><rect x="13" y="13" width="7" height="7" />
    </svg>
    <span><strong>3.</strong> Featured on the wall</span>
  </li>
</ol>

<section class="card" id="submit-section">
  <h3 class="card-title">Brew &amp; Share Your Chai Story</h3>
  <form action="/submit" method="POST" novalidate>
    <div class="form-row">
      <div class="form-group">
        <label for="name">Your Name</label>
        <input
          type="text"
          id="name"
          name="name"
          value="{{ form_data.get('name', '') }}"
          maxlength="100"
          placeholder="e.g. Priya Sharma"
          autocomplete="name"
          class="{% if errors.get('name') %}is-invalid{% endif %}"
          {% if errors.get('name') %}aria-describedby="name-error"{% endif %}
          required
        >
        {% if errors.get('name') %}
          <span id="name-error" class="error-msg" role="alert">{{ errors.name }}</span>
        {% endif %}
      </div>

      <div class="form-group">
        <label for="city">City / Town</label>
        <input
          type="text"
          id="city"
          name="city"
          value="{{ form_data.get('city', '') }}"
          maxlength="100"
          placeholder="e.g. Jaipur"
          autocomplete="address-level2"
          class="{% if errors.get('city') %}is-invalid{% endif %}"
          {% if errors.get('city') %}aria-describedby="city-error"{% endif %}
          required
        >
        {% if errors.get('city') %}
          <span id="city-error" class="error-msg" role="alert">{{ errors.city }}</span>
        {% endif %}
      </div>
    </div>

    <div class="form-group">
      <label for="contact">Contact Information (Email or Mobile)</label>
      <input
        type="text"
        id="contact"
        name="contact"
        value="{{ form_data.get('contact', '') }}"
        maxlength="255"
        placeholder="e.g. priya@example.com or +91 98765 43210"
        autocapitalize="none"
        spellcheck="false"
        class="{% if errors.get('contact') %}is-invalid{% endif %}"
        {% if errors.get('contact') %}aria-describedby="contact-error"{% endif %}
        required
      >
      <div class="field-hint">
        We&rsquo;ll only reach out if your story is featured in the campaign. Never published.
      </div>
      {% if errors.get('contact') %}
        <span id="contact-error" class="error-msg" role="alert">{{ errors.contact }}</span>
      {% endif %}
    </div>

    <div class="form-group">
      <label for="story">Your Chai Story</label>
      <textarea
        id="story"
        name="story"
        rows="6"
        maxlength="{{ max_story_length }}"
        placeholder="Tell us about the setting, the aroma, the conversations, or the quiet moment that made this chai break special..."
        class="{% if errors.get('story') %}is-invalid{% endif %}"
        {% if errors.get('story') %}aria-describedby="story-error"{% endif %}
        required
      >{{ form_data.get('story', '') }}</textarea>
      <div class="char-counter"><span id="char-count">0</span> / {{ max_story_length }}</div>
      {% if errors.get('story') %}
        <span id="story-error" class="error-msg" role="alert">{{ errors.story }}</span>
      {% endif %}
    </div>

    <div class="form-group checkbox-group">
      <label class="checkbox-label" for="consent">
        <input
          type="checkbox"
          id="consent"
          name="consent"
          value="true"
          {% if form_data.get('consent') %}checked{% endif %}
          {% if errors.get('consent') %}aria-describedby="consent-error"{% endif %}
        >
        <span>I confirm this is my own authentic story and agree to have it featured on the Kadak Chai Co. wall if approved.</span>
      </label>
      {% if errors.get('consent') %}
        <span id="consent-error" class="error-msg" role="alert">{{ errors.consent }}</span>
      {% endif %}
    </div>

    <button type="submit" class="btn btn-primary" id="submit-btn">Submit Chai Story</button>
  </form>
</section>

<section class="wall-section">
  <div class="wall-header">
    <h3 class="wall-title">Approved #MyChaiBreak Stories</h3>
    <p class="wall-subtitle">Recent stories celebrating warm cups and cherished moments across the country.</p>
  </div>

  {% if entries %}
    <div class="stories-grid">
      {% for entry in entries %}
        <article class="story-card">
          <div>
            {% if entry.ai_caption %}
              <h4 class="story-caption">&ldquo;{{ entry.ai_caption }}&rdquo;</h4>
            {% endif %}
          </div>
          <div class="story-meta">
            <span class="story-author">&mdash; {{ entry.name.split()[0] }}</span>
            {% if entry.created_at %}
              <span class="story-date">{{ entry.created_at.strftime('%B %d, %Y') }}</span>
            {% endif %}
            {% if entry.ai_category %}
              <span class="badge badge-category">{{ entry.ai_category }}</span>
            {% endif %}
          </div>
        </article>
      {% endfor %}
    </div>
  {% else %}
    <div class="empty-wall-notice">
      <p>Be the first to share your chai story.</p>
    </div>
  {% endif %}
</section>
{% endblock %}

{% block scripts %}
<script>
  (function () {
    var storyInput = document.getElementById("story");
    var charCount = document.getElementById("char-count");
    var counterBox = charCount ? charCount.parentElement : null;

    if (storyInput && charCount) {
      function updateCount() {
        var len = storyInput.value.length;
        charCount.textContent = len;
        if (counterBox) {
          if (len >= 300) {
            counterBox.style.color = "#8c2424";
            counterBox.style.fontWeight = "700";
          } else if (len >= 270) {
            counterBox.style.color = "#d9822b";
            counterBox.style.fontWeight = "600";
          } else {
            counterBox.style.color = "";
            counterBox.style.fontWeight = "";
          }
        }
      }
      storyInput.addEventListener("input", updateCount);
      updateCount();
    }

    var submitForm = document.querySelector("form[action='/submit']");
    var submitBtn = document.getElementById("submit-btn");
    var originalBtnText = submitBtn ? submitBtn.textContent : "Submit Chai Story";

    if (submitForm && submitBtn) {
      submitForm.addEventListener("submit", function () {
        setTimeout(function () {
          submitBtn.disabled = true;
          submitBtn.textContent = "Brewing your caption...";
        }, 0);
      });

      window.addEventListener("pageshow", function () {
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.textContent = originalBtnText;
        }
      });
    }
  })();
</script>
{% endblock %}

